node -e '
async function testContract(rpcUrl, addr) {
  try {
    const res = await fetch(rpcUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        jsonrpc: "2.0",
        method: "eth_getCode",
        params: [addr, "latest"],
        id: 1
      })
    });
    const data = await res.json();
    return data.result && data.result.length > 2;
  } catch (e) {
    return false;
  }
}
async function getNameSymbol(rpcUrl, addr) {
  // name() 0x06fdde03, symbol() 0x95d89b41
  for (const sig of ["0x06fdde03", "0x95d89b41"]) {
    const res = await fetch(rpcUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        jsonrpc: "2.0",
        method: "eth_call",
        params: [{ to: addr, data: sig }, "latest"],
        id: 1
      })
    });
    const data = await res.json();
    console.log(addr, sig, data);
  }
}
async function run() {
  const wethSepolia = "0x980B62Da83eFf3D4576C647993b0c1D730E23594";
  console.log("Sepolia WETH:", await testContract("https://sepolia-rollup.arbitrum.io/rpc", wethSepolia));
  await getNameSymbol("https://sepolia-rollup.arbitrum.io/rpc", wethSepolia);

  // Test native USDC on Arbitrum Sepolia: 0x75faf114eafb1BDbe2F0316DF893fd58CE46AA4d
  const usdcSepolia = "0x75faf114eafb1BDbe2F0316DF893fd58CE46AA4d";
  console.log("Sepolia USDC:", await testContract("https://sepolia-rollup.arbitrum.io/rpc", usdcSepolia));
  await getNameSymbol("https://sepolia-rollup.arbitrum.io/rpc", usdcSepolia);
}
run();
'

