func NewForwarder(targets []string, config *ForwarderConfig) *TxForwarder {
	dialer := net.Dialer{
		Timeout:   5 * time.Second,
		KeepAlive: 2 * time.Second,
	}

	transport := &http.Transport{
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			if network == "tcp" {
				return dialer.DialContext(ctx, "tcp4", addr)
			}
			return dialer.DialContext(ctx, network, addr)
		},
		MaxIdleConns:          config.MaxIdleConnections,
		MaxIdleConnsPerHost:   config.MaxIdleConnections,
		IdleConnTimeout:       config.IdleConnectionTimeout,
		TLSHandshakeTimeout:   5 * time.Second,
		ExpectContinueTimeout: 1 * time.Second,
	}
	return &TxForwarder{
		targets:               targets,
		timeout:               config.ConnectionTimeout,
		transport:             transport,
		tryNewForwarderErrors: regexp.MustCompile(`(?i)(^http:|^json:|^i/0|timeout exceeded|no such host)`),
	}
}

func (f *TxForwarder) ctxWithTimeout() (context.Context, context.CancelFunc) {
	if f.timeout == time.Duration(0) {
		return context.WithCancel(f.ctx)
	}
	return context.WithTimeout(f.ctx, f.timeout)
}

func (f *TxForwarder) PublishTransaction(inctx context.Context, tx *types.Transaction, options *arbitrum_types.ConditionalOptions) error {
	if !f.enabled.Load() {
		return ErrNoSequencer
	}
	ctx, cancelFunc := f.ctxWithTimeout()
	defer cancelFunc()
	for pos, rpcClient := range f.rpcClients {
		var err error
		if options == nil {
			err = f.ethClients[pos].SendTransaction(ctx, tx)
		} else {
			err = arbitrum.SendConditionalTransactionRPC(ctx, rpcClient, tx, options)
		}
		if err != nil {
			if pos == 0 {
				log.Warn("error forwarding transaction trying different target", "current target", f.targets[pos], "err", err)
			} else {
				log.Warn("error forwarding transaction to a backup target", "target", f.targets[pos], "pos", pos, "total targets", len(f.rpcClients), "err", err)
			}
		}
		if err == nil || !f.tryNewForwarderErrors.MatchString(err.Error()) {
			return err
		}
	}
	log.Error("Failed to publish transaction to any of the forwarding targets", "numTargets", len(f.rpcClients))
	return errors.New("failed to publish transaction to any of the forwarding targets")
}

func (f *TxForwarder) PublishExpressLaneTransaction(inctx context.Context, msg *timeboost.ExpressLaneSubmission) error {
	if !f.enabled.Load() {
		return ErrNoSequencer
	}
	ctx, cancelFunc := f.ctxWithTimeout()
	defer cancelFunc()
	for pos, rpcClient := range f.rpcClients {
		err := sendExpressLaneTransactionRPC(ctx, rpcClient, msg)
		if err != nil {
			log.Warn("error forwarding express lane transaction to a backup target", "target", f.targets[pos], "err", err)
		}
		if err == nil || !f.tryNewForwarderErrors.MatchString(err.Error()) {
			return err
		}
	}
	log.Error("Failed to publish transaction to any of the forwarding targets", "numTargets", len(f.rpcClients))
	return errors.New("failed to publish transaction to any of the forwarding targets")
}

func sendExpressLaneTransactionRPC(ctx context.Context, rpcClient *rpc.Client, msg *timeboost.ExpressLaneSubmission) error {
	jsonMsg, err := msg.ToJson()
	if err != nil {
		return err
	}
	return rpcClient.CallContext(ctx, nil, "timeboost_sendExpressLaneTransaction", jsonMsg)
}

